import{_ as e}from"./chunks/projects.BdG50VF9.js";import{_ as t,c as r,o,a2 as i}from"./chunks/framework.CIiVzG-O.js";const m=JSON.parse('{"title":"提交前看一遍","description":"在项目文件夹里逐个查看改动文件，并在 qDiff 里直接提交。","frontmatter":{"title":"提交前看一遍","description":"在项目文件夹里逐个查看改动文件，并在 qDiff 里直接提交。"},"headers":[],"relativePath":"zh-CN/guide/projects.md","filePath":"zh-CN/guide/projects.md","lastUpdated":1793948370000}'),s={name:"zh-CN/guide/projects.md"};function l(p,a,c,d,h,n){return o(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="提交前看一遍" tabindex="-1">提交前看一遍 <a class="header-anchor" href="#提交前看一遍" aria-label="Permalink to &quot;提交前看一遍&quot;">​</a></h1><p>每次提交前问一句「我到底改了什么」，都很值得。用 qDiff 打开项目文件夹， 答案已经摆好了。</p><img src="'+e+'" alt="改动文件列表与右侧彩色差异" class="guide-shot"><h2 id="打开项目文件夹" tabindex="-1">打开项目文件夹 <a class="header-anchor" href="#打开项目文件夹" aria-label="Permalink to &quot;打开项目文件夹&quot;">​</a></h2><p>从「文件 → 打开」选一个 Git 项目文件夹，或者直接拖进窗口。qDiff 会把你动过的 文件收成一列。</p><h2 id="先看列表-再看差异" tabindex="-1">先看列表，再看差异 <a class="header-anchor" href="#先看列表-再看差异" aria-label="Permalink to &quot;先看列表，再看差异&quot;">​</a></h2><p>每个文件都标着它的状态：新增、修改、删除。点开一个，右边就显示里面具体改了 什么，颜色和按词高亮跟普通文件比较完全一样。</p><p>一个一个看过去就好，列表会记住你看到哪儿，改动再多也不容易漏。</p><h2 id="在同一个窗口里收尾" tabindex="-1">在同一个窗口里收尾 <a class="header-anchor" href="#在同一个窗口里收尾" aria-label="Permalink to &quot;在同一个窗口里收尾&quot;">​</a></h2><p>确认没问题，直接在这里提交。更新、推送、还原、解决冲突也都能在比较界面里完成， 不用再开别的工具，也不需要账号。</p><div class="tip custom-block"><p class="custom-block-title">不是项目文件夹？</p><p>普通文件夹照样能当文件夹来比，<a href="./folders.html">比较文件夹</a>在任何目录都可用。</p></div><p>接下来：<a href="./more.html">图片、压缩包与更多玩法</a>。</p>',12)])])}const u=t(s,[["render",l]]);export{m as __pageData,u as default};
